import {listFreeNvidiaModels, discoverNvidiaModels, keyFingerprint} from '../services/ai/nvidia-discovery.mjs';
const split=v=>Array.isArray(v)?v:String(v||'').split(/[\n,،]+/);
const clean=(v,max,label)=>{const s=String(v||'').trim();if(s.length>max)throw Error(`${label} طويل جداً`);return s};
export function createAiWebService({getUser,saveUser,getUserNumbers,updateNumber,ai,clearMemory,listFree=listFreeNvidiaModels,discover=discoverNvidiaModels,inMemoryDB=null}) {
 // [META-AI-SOCK-FIX v8.21.0] أي سوكت حيّ (لا نعتمد على readyState الذي يعطي null هنا)
 async function _keylessAsk(prompt){try{const mod=await import('../services/ai/keyless-provider.mjs');return await mod.askKeyless(prompt,{timeoutMs:30000})}catch{return null}}
 function _metaSock(uid){try{const sessions=inMemoryDB?.sessions;const pick=v=>{const s=v?.sock||v;return s&&typeof s.sendMessage==='function'?s:null};const direct=pick(sessions?.get?.(String(uid)));if(direct)return direct;if(sessions&&typeof sessions[Symbol.iterator]==='function'){for(const [k,v] of sessions){if(String(k).startsWith(String(uid)+'_')){const s=pick(v);if(s)return s}}}return null}catch{return null}}
 const cache=new Map(),jobs=new Map();
 const getKey=uid=>ai.getNvidiaKey(String(uid))||'';
 function number(uid,id){const n=getUserNumbers(String(uid)).find(x=>String(x.id)===String(id));if(!n)throw Error('الرقم غير موجود');return n}
 function overview(uid){uid=String(uid);const u=getUser(uid),key=getKey(uid),saved=u.aiDiscoveredModels;return {hasKey:!!key,personalKey:!!u.nvidiaKey,model:ai.getUserSelectedModel(uid),systemPrompt:u.aiSystemPrompt||'',temperature:typeof u.aiTemperature==='number'?u.aiTemperature:0.7,maxTokens:typeof u.aiMaxTokens==='number'?u.aiMaxTokens:300,blacklist:u.aiBlacklist||[],stats:u.aiStats||{requests:0,tokens:0},scan:saved?.keyFingerprint===keyFingerprint(key)&&saved.checkedAt?{checkedAt:saved.checkedAt,tested:saved.tested,count:saved.models?.length||0}:null,numbers:getUserNumbers(uid).map(n=>({id:n.id,number:n.number,label:n.label,aiEnabled:!!n.aiEnabled,aiPrompt:n.aiPrompt||'',aiSchedule:n.aiSchedule||null,aiTargets:n.aiTargets||[],aiGroups:n.aiGroups||[]})),metaAi:{enabled:u.metaAiEnabled!==false,ok:Number(u.aiStats?.metaAi||0)},keyless:{ok:Number(u.aiStats?.keyless||0)}}}
 async function models(uid,{refresh=false}={}){uid=String(uid);const key=getKey(uid);if(!key)throw Error('أضف مفتاح NVIDIA أولاً لجلب النماذج');const fp=keyFingerprint(key),saved=getUser(uid).aiDiscoveredModels;
   if(!refresh&&saved?.keyFingerprint===fp&&Array.isArray(saved.models)&&saved.checkedAt)return {models:saved.models,verified:true,checkedAt:saved.checkedAt,tested:saved.tested};
   const c=cache.get(uid);if(!refresh&&c?.fp===fp&&Date.now()-c.at<15*60*1000)return {models:c.models,verified:false};
   const result=await listFree(key);if(keyFingerprint(getKey(uid))!==fp)throw Error('تغيّر المفتاح؛ أعد جلب النماذج');cache.set(uid,{fp,at:Date.now(),models:result});return {models:result,verified:false};
 }
 function scan(uid){uid=String(uid);const key=getKey(uid);if(!key)throw Error('أضف مفتاح NVIDIA أولاً');const active=jobs.get(uid);if(active?.state==='running')return {...active};const fp=keyFingerprint(key),job={state:'running',done:0,total:0};jobs.set(uid,job);
  Promise.resolve().then(()=>discover(key,{onProgress:(done,total)=>{job.done=done;job.total=total}})).then(result=>{if(keyFingerprint(getKey(uid))!==fp)throw Error('تغيّر المفتاح أثناء الفحص، لم تُحفظ النتائج');saveUser(uid,{aiDiscoveredModels:{keyFingerprint:fp,models:result.models,tested:result.tested,checkedAt:Date.now()}});job.state='done';job.count=result.models.length;job.total=result.tested;cache.delete(uid)}).catch(err=>{job.state='error';job.error=String(err?.message||'فشل الفحص')});return {...job};
 }
 return {overview,models,scan,scanStatus:uid=>({...jobs.get(String(uid))||{state:'idle'}}),
  saveKey(uid,value){uid=String(uid);const key=clean(value,500,'المفتاح');if(!/^nvapi-\S{14,}$/.test(key))throw Error('مفتاح NVIDIA غير صالح');ai.setUserNvidiaKey(uid,key);cache.delete(uid);return overview(uid)},
  deleteKey(uid){uid=String(uid);ai.setUserNvidiaKey(uid,null);cache.delete(uid);return overview(uid)},
  async select(uid,id){uid=String(uid);const m=await models(uid);const c=cache.get(uid);const cached=c?.fp===keyFingerprint(getKey(uid))&&Date.now()-c.at<15*60*1000?c.models:[];if(!m.models.some(x=>x.id===id)&&!cached.some(x=>x.id===id))throw Error('النموذج غير موجود في القائمة الحالية؛ حدّث القائمة');ai.setUserModel(uid,id);return {ok:true}},
  settings(uid,input){uid=String(uid);const temp=Number(input.temperature),max=Number(input.maxTokens);if(!Number.isFinite(temp)||temp<0||temp>2||!Number.isInteger(max)||max<50||max>4000)throw Error('الإبداع بين 0 و2 وطول الرد بين 50 و4000');const words=split(input.blacklist).map(x=>clean(x,100,'الكلمة')).filter(Boolean);if(words.length>50)throw Error('الحد الأقصى 50 كلمة');saveUser(uid,{aiSystemPrompt:clean(input.systemPrompt,2000,'البرومبت'),aiTemperature:temp,aiMaxTokens:max,aiBlacklist:words});return {ok:true}},
  saveNumber(uid,id,input){uid=String(uid);number(uid,id);if(typeof input.aiEnabled!=='boolean')throw Error('حالة الرقم غير صالحة');/* [AIWEB-KEYLESS v8.34.0] كان تفعيل ذكاء الرقم يطلب مفتاح NVIDIA إلزامياً؛ الآن يعمل بذكاء ميتا/المزوّد المجاني بلا مفتاح */const targets=split(input.aiTargets).map(x=>String(x).trim()).filter(Boolean).map(x=>x.replace(/\D/g,''));if(targets.length>100||targets.some(x=>x.length<7||x.length>15))throw Error('أدخل أرقاماً دولية صحيحة');const groups=split(input.aiGroups).map(x=>String(x).trim()).filter(Boolean);if(groups.length>100||groups.some(x=>!/^[A-Za-z0-9._:-]{3,128}@g\.us$/.test(x)))throw Error('أدخل معرفات مجموعات صحيحة');let schedule=null;if(input.scheduleFrom||input.scheduleTo){const t=/^(?:[01]\d|2[0-3]):[0-5]\d$/;if(!t.test(input.scheduleFrom)||!t.test(input.scheduleTo))throw Error('أدخل بداية ونهاية الجدول');schedule={from:input.scheduleFrom,to:input.scheduleTo}}const patch={aiEnabled:input.aiEnabled,aiPrompt:clean(input.aiPrompt,2000,'برومبت الرقم'),aiTargets:targets,aiGroups:groups,aiSchedule:schedule};if(!updateNumber(uid,id,patch))throw Error('تعذّر حفظ إعداد الرقم');return {ok:true}},
  async test(uid,text){uid=String(uid);const msg=clean(text,2000,'رسالة الاختبار');if(!msg)throw Error('أدخل رسالة الاختبار');/* [AIWEB-KEYLESS v8.34.0] بلا مفتاح نستخدم مسار ميتا/المزوّد المجاني */const result=await ai.getAiReply(uid,getUser(uid).aiSystemPrompt||null,'مستخدم',msg,`webtest_${uid}`);if(!result)throw Error('لم يرد أي مزوّد (ميتا/مجاني/المفتاح). أعد المحاولة بعد لحظات أو تحقق من إتاحة النموذج للحساب.');return {reply:result,via:getKey(uid)?'nvidia':'keyless'}},
  clear(uid){return {count:clearMemory(String(uid))}},
  // [META-AI-WEB v8.21.0] تفعيل/إيقاف ذكاء ميتا (بلا مفتاح) من لوحة الويب
  async keylessTest(uid){uid=String(uid);const reply=await _keylessAsk('اكتب جملة قصيرة بالعربية تقول: تم اختبار الاتصال بنجاح.');if(!reply)throw Error('لم يصل رد من المزوّد بلا مفتاح (تحقق من اتصال الخادم بالإنترنت).');const u=getUser(uid)||{},st=u.aiStats||{};saveUser(uid,{aiStats:{...st,keyless:(st.keyless||0)+1,lastAt:Date.now()}});return {ok:true,reply}},
  metaAi(uid,enabled){uid=String(uid);if(typeof enabled!=='boolean')throw Error('حالة غير صالحة');saveUser(uid,{metaAiEnabled:enabled});return {ok:true,enabled}},
  async metaAiTest(uid){uid=String(uid);const sock=typeof _metaSock==='function'?_metaSock(uid):null;if(!sock)throw Error('لا يوجد رقم واتساب متصل الآن. اربط رقماً أولاً.');const mod=await import('../services/ai/meta-ai-provider.mjs');const client=mod.createMetaAiClient({sock,timeoutMs:20000});const reply=await client.ask('اكتب جملة قصيرة بالعربية تقول: تم اختبار الاتصال بنجاح.');if(!reply){
   // [KEYLESS-HTTP v8.21.1] حساب Business لا يملك محادثة Meta AI ⇒ نجرّب المزوّد بلا مفتاح
   const alt=await _keylessAsk('اكتب جملة قصيرة بالعربية تقول: تم اختبار الاتصال بنجاح.');
   if(alt)return {ok:true,reply:alt,via:'keyless',note:'Meta AI غير متاح (حساب Business غالباً) — نجح المزوّد بلا مفتاح'};
   throw Error('لم يصل رد من Meta AI ولا من المزوّد بلا مفتاح. الأسباب: حساب Business لا يملك محادثة Meta AI، أو الخادم لا يصل إلى الإنترنت.');
 }const u=getUser(uid)||{},st=u.aiStats||{};saveUser(uid,{aiStats:{...st,metaAi:(st.metaAi||0)+1,lastAt:Date.now()}});return {ok:true,reply}}
 };
}
